                "subtitle": "과학적 발견율과 독립 코호트 검증",
                "desc": "전체 프레임워크는 95.24%의 감사 평가 과학적 발견율을 기록해 일반 목적 실행기나 도메인 전용 연구 에이전트를 뛰어넘는 성능을 보여줬는데요. 대표적인 결과들은 신경정신과적 증상과 치매 위험, 아밀로이드 공간적 안정성 등을 다루고 있으며, 독립된 에이디엔아이(ADNI)와 에이블(AIBL) 코호트에서도 핵심 연관성이 뒷받침되었다는 거예요. 뭔 소리냐면, 다른 데이터셋에서도 똑같이 통한다는 걸 증명해 냈다는 말이에요.",
