            "easy1_desc": "요즘 거대언어모델(LLM)을 써서 AI 에이전트를 만드는 경우가 늘고 있는데요, 정작 이 모델들이 에이전트를 얼마나 잘 만드는지 평가하는 기준은 거의 없었습니다. 그래서 연구진은 실제 기업의 응용 과학자가 일하는 환경을 본떠서 AppSci-Bench라는 평가 도구를 만들었습니다. 요구 사항을 파악하고 인프라를 탐색하며 실험을 설계하는 과정을 모델이 직접 수행하도록 한 거예요.",
            "easy1_evidence": "While many benchmarks assess the quality of LLM- powered agents, few ascertain how good LLMs are at building them.",
