            "easy1_title": "기존 강수 예측 모델은 왜 틀렸고 고치려면 뭐가 문제였나",
            "easy1_desc": "강수 예측 모델들은 비가 얼마나 오는지, 어디에 내리는지, 모양은 어떤지 같은 부분에서 자꾸 틀리는데요, 이걸 고치려고 기본 모델 전체를 다시 학습시키는 건 계산 비용이 너무 많이 들고 복잡한 수정이 필요하다는 문제가 있었거든요. 뭔 소리냐면, 조금만 고치려 해도 전체를 다시 뜯어고쳐야 해서 손이 많이 간다는 말이에요. 쉽게 말하면, 비용과 번거로움 때문에 수정 자체가 쉽지 않았던 셈이라는 겁니다.",
            "easy1_evidence": "Addressing these errors by retraining nowcaster backbones can be computationally expensive and requires architecture-specific modifications.",
            "easy2_title": "기본 모델은 그대로 두고 가벼운 보정기를 따로 붙여 해결했다",
            "easy2_desc": "그래서 연구진은 기본 모델은 얼려 둔 채로 결과물만 따로 다듬어 주는 분리형 잔차 보정 프레임워크인 CorrectCast를 제안했는데요, 무거운 뼈대를 건드릴 필요 없이 가벼운 보정기만 따로 학습시키면 된다는 거예요. 이렇게 하면 계산 부담은 줄이면서도 여러 예측 모델에 공통으로 쓸 수 있는 보정 창구를 마련할 수 있는 장점이 있는데요, 대신 기본 예측 결과와 과거 관측 데이터가 제대로 뒷받침되어야 한다는 조건도 같이 따라온다는 겁니다.",
            "easy2_evidence": "To overcome these limitations, we propose CorrectCast, a decoupled residual correction framework that refines completed nowcasts while keeping the base nowcaster frozen.",
            "topic": "기본 예측 모델을 건드리지 않고 멀티모달 맥락과 규모별 조절을 이용해 강수 예측 오차를 효율적으로 바로잡는 CorrectCast 프레임워크를 제안했다는 내용이에요.",
            "topic_evidence": "To overcome these limitations, we propose CorrectCast, a decoupled residual correction framework that refines completed nowcasts while keeping the base nowcaster frozen.",
