                "desc": "기존 강수 예측 모델들을 그대로 둔 채 예측된 강수 필드 위에서만 작동하는 가벼운 보정기를 따로 학습시켰는데요, 뭔 소리냐면, 복잡한 기본 구조를 건드리지 않고도 연산 부담을 크게 덜어낸다는 말이에요.",
                "evidence": "By operating on predicted precipitation fields, CorrectCast requires training only a lightweight corrector, reducing computational overhead while providing a unified correction interface across different nowcasting models."
