            "easy1_desc": "연구진은 아날로그 회로 관련 논문의 문제 50개로 만든 벤치마크를 가져와서, AI 모델 73개의 실력이 얼마나 빨리 좋아지는지 확인해 봤는데요. 정답과 채점 기준을 바탕으로 GPT-6 Luna가 채점하는 방식을 썼다는 겁니다. 2024년 5월부터 2026년 11월 사이에 나온 모델들을 대상으로 살펴봤더니, 최고 점수가 30개월 만에 28.83%에서 98.33%로 올랐다고 해요. 쉽게 말하면, 옛날에는 AI가 겨우 풀던 교재 문제를 이제는 거의 다 맞힐 정도로 실력이 엄청나게 좋아졌다는 말이에요.",
