                "subtitle": "세분화 모호성과 PEETS 제안",
                "desc": "여행 부가 상품을 추천할 때 상품 유형은 비슷해도 가격과 보장이 달라서 생기는 모호성을 풀려고 PEETS라는 학습용 프레임워크를 도입했어요. 상품 카테고리의 관계와 개인의 선호도를 따로 나눠서 학습하도록 만든 구조라는 거예요.",
                "evidence": "This setting creates a granularity ambiguity: SKUs within one product type share semantics but differ in price and coverage, while rejecting one offer does not imply disinterest in the entire type."
