            "easy1_title": "스스로 문제를 내고 답을 찾아보게 해 봤는데요",
            "easy1_desc": "연구진은 큐원(Qwen3-4B) 모델이 루아(Lua 5.1) 프로그램을 직접 만들고, 인터프리터가 그 답을 검증하는 방식을 써 봤거든요. 모델이 네 번 중 한 번이라도 틀린 문제들을 모아서 학습 풀을 만들고, 매 라운드마다 데이터 양을 늘려가며 어댑터를 새로 학습시켰다는 말이에요. 원래 시험에서는 사전에 정한 기준을 통과했지만, 새롭게 만든 시험에서는 라운드마다 결과가 조금씩 달랐다는 겁니다. 쉽게 말하면, 스스로 문제를 풀게 만든 데이터로 모델을 훈련해 본 셈이에요.",
            "easy1_evidence": "Qwen3-4B proposed Lua 5.1 programs; those it predicted wrong at least once in four samples joined a pool labelled by the interpreter, each round adding twice as many programs as the last (300, 900, 2100 in total), and each round trained a fresh adapter from the base on the pool.",
            "easy2_title": "정확도가 두 배로 뛰었지만 한계도 분명했거든요",
            "easy2_desc": "그 결과 새로 만든 2340문항짜리 시험에서 정확도가 8.3퍼센트에서 16.7퍼센트로 올랐는데요, 1라운드에서는 효과가 없었지만 2라운드와 3라운드에서 점수가 평균적으로 올랐다는 거예요. 대신 기본 데이터로 똑같이 맞췄을 때와 비교하면 2.1포인트 차이가 나서 확실한 우위라고 보기는 어렵다는 단점도 있거든요. 다른 설정이나 더 큰 27B 모델에서는 아예 효과가 없었다는 점도 같이 나타났다는 겁니다.",
