            "easy1_desc": "컴퓨터를 쓸 줄 아는 인공지능 에이전트(컴퓨터 조작 에이전트)를 만들 때 지금까지는 영상을 캡처 화면으로만 쪼개서 배워 왔는데요, 그러다 보니 영상에 들어 있는 풍부한 소리와 화면 속 움직임을 제대로 쓰지 못했다는 겁니다. 뭔 소리냐면, 화면만 뚝뚝 끊어 보는 방식으로는 사람이 설명해 주는 소리나 자연스러운 흐름을 놓치기 쉽다는 말이에요. 연구진은 바로 이 점에 착안해서 소리와 화면을 함께 이해하는 방식을 찾아보기로 했는데요, 쉽게 말하면 영상 그 자체를 통째로 경험으로 삼아 컴퓨터 쓰는 법을 배우게 하겠다는 겁니다.",
            "easy1_evidence": "However, existing approaches to learning from video demonstrations typically convert videos into screenshot-based action trajectories, rather than directly leveraging their rich audio-visual information.",
