            "easy2_desc": "그래서 연구진은 브이엑스(VEX)라는 틀을 내놓았는데요, 보고 행동하고 다시 보는 방식을 따라 튜토리얼(자습용) 영상의 시각 자료와 음성 설명을 바탕으로 절차적 지침을 뽑아내고 작업을 수행한 뒤 자기 실행 과정을 영상으로 다시 보며 검증한다는 겁니다. 여기에 9B(90억 개) 규모의 비디오-살몬-브이엑스(video-SALMONN-VEX) 모델을 세우고, 행동 기반 가이드 최적화(AGGO)라는 강화학습 방법으로 영상에서 얻은 지침을 다듬었는데요, 오에스월드(OSWorld) 실험 결과 기존 큐원3.5(Qwen3.5) 뼈대 모델보다 작업 성공률이 22% 상대적으로 좋아졌다는 장점이 있는데, 대신 영상 데이터와 강화학습 과정을 거쳐야 한다는 복잡함도 같이 따라온다는 겁니다.",
