                "subtitle": "브이엑스(VEX) 프레임워크 도입",
                "desc": "연구진은 시각 자료와 음성 설명이 담긴 튜토리얼 영상에서 절차적 지침을 뽑아내고, 에이전트가 직접 작업을 수행한 뒤 자신의 실행 과정을 영상으로 다시 보며 진행 상황을 확인하는 시청-행동-재시청 방식을 제안했어요. 뭔 소리냐면, 남이 하는 영상을 보고 따라 한 뒤에 내가 한 것도 영상으로 다시 보면서 제대로 했는지 점검한다는 말이에요.",
